parameters.jsonBody:
{
  "query": "query($id: ID!) { product(id: $id) { id title description category { name } handle } }",
  "variables": { "id": "{{ $json.productId }}" }
}

parameters.jsCode:
// Extract product data for AI processing
const product = $json.body.data.product;

return {
  productId: product.id,
  title: product.title,
  currentDescription: product.description || 'No description provided',
  category: product.category?.name || 'General',
  handle: product.handle,
  brandVoice: $json.brandVoice || 'Professional',
  keywords: $json.keywords || '',
  length: $json.length || 'Medium'
};

parameters.prompt:
Generate SEO-optimized meta tags for an e-commerce product.

Product Title: {{ $json.title }}
Product Description: {{ $json.currentDescription }}
Primary Keyword: {{ $json.keywords.split(',')[0] || $json.title }}
Category: {{ $json.category }}

Your task:
1. Create a Meta Title (50-60 characters max) that includes the primary keyword
2. Create a Meta Description (150-160 characters max) that includes the primary keyword and a subtle call-to-action

Respond ONLY in this JSON format:
{
  "metaTitle": "your meta title here",
  "metaDescription": "your meta description here"
}

parameters.jsCode:
// Parse AI responses and prepare for Shopify update
const rewrittenDescription = $json.output || $json.body;
const seoRaw = $json.body;

let seoData = { metaTitle: '', metaDescription: '' };

// Try to parse SEO response as JSON
try {
  const jsonMatch = seoRaw.match(/\{[^}]+\}/);
  if (jsonMatch) {
    seoData = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // If JSON parsing fails, try to extract text
  const lines = seoRaw.split('\n');
  seoData.metaTitle = lines[0]?.replace(/Meta Title:|:/, '').trim() || '';
  seoData.metaDescription = lines[1]?.replace(/Meta Description:|:/, '').trim() || '';
}

return {
  rewrittenDescription,
  metaTitle: seoData.metaTitle.substring(0, 60),
  metaDescription: seoData.metaDescription.substring(0, 160),
  productId: $json.productId,
  handle: $json.handle,
  previousDescription: $json.currentDescription
};

// Log the execution and prepare response
const timestamp = new Date().toISOString();

return {
  success: true,
  message: 'Product description rewritten and published successfully',
  details: {
    productId: $json.productId,
    handle: $json.handle,
    timestamp,
    changes: {
      description: 'Updated',
      metaTitle: $json.metaTitle,
      metaDescription: $json.metaDescription
    },
    previousDescription: $json.previousDescription
  }
};
